public class EternalDensityContainer extends PEHandContainer {

	private final EternalDensityInventory inventory;

	public static EternalDensityContainer fromNetwork(int windowId, Inventory playerInv, FriendlyByteBuf data) {
		return new EternalDensityContainer(windowId, playerInv, data.readEnum(InteractionHand.class), data.readByte(), true);
	}

	public EternalDensityContainer(int windowId, Inventory playerInv, InteractionHand hand, int selected) {
		this(windowId, playerInv, hand, selected, false);
	}

	private EternalDensityContainer(int windowId, Inventory playerInv, InteractionHand hand, int selected, boolean remote) {
		super(PEContainerTypes.ETERNAL_DENSITY_CONTAINER, windowId, playerInv, hand, selected);
		inventory = new EternalDensityInventory(this.stack, remote);
		for (int i = 0; i < 3; ++i) {
			for (int j = 0; j < 3; ++j) {
				this.addSlot(new SlotGhost(inventory, j + i * 3, 62 + j * 18, 26 + i * 18, SlotPredicates.HAS_EMC));
			}
		}
		addPlayerInventory(8, 93);
	}

	public boolean isWhitelistMode() {
		return getStack().getOrDefault(PEDataComponentTypes.GEM_DATA, GemData.EMPTY).isWhitelist();
	}

	@NotNull
	@Override
	public ItemStack quickMoveStack(@NotNull Player player, int slotIndex) {
		if (slotIndex > 8) {
			Slot slot = tryGetSlot(slotIndex);
			if (slot != null) {
				ItemHandlerHelper.insertItem(inventory, slot.getItem().copyWithCount(1), false);
			}
		}
		return ItemStack.EMPTY;
	}

	@Override
	public void clickPostValidate(int slotIndex, int button, @NotNull ClickType flag, @NotNull Player player) {
		Slot slot = tryGetSlot(slotIndex);
		if (!(slot instanceof ISlotGhost ghost) || !ghost.tryClear()) {
			super.clickPostValidate(slotIndex, button, flag, player);
		}
	}

	@Override
	public boolean canDragTo(@NotNull Slot slot) {
		return false;
	}
}

package moze_intel.projecte.gameObjs.container.inventory;

import java.util.Set;
import moze_intel.projecte.components.GemData;
import moze_intel.projecte.gameObjs.registries.PEDataComponentTypes;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.ItemStackLinkedSet;
import net.neoforged.neoforge.items.ItemStackHandler;
import org.jetbrains.annotations.NotNull;

public class EternalDensityInventory extends ItemStackHandler {

	private final ItemStack invItem;
	private final boolean remote;

	public EternalDensityInventory(ItemStack stack, boolean remote) {
		super(9);
		this.invItem = stack;
		this.remote = remote;
		int slot = 0;
		for (ItemStack whitelisted : invItem.getOrDefault(PEDataComponentTypes.GEM_DATA, GemData.EMPTY).whitelist()) {
			if (!whitelisted.isEmpty()) {
				//Note: We copy it so that it doesn't mutate our gem data's stack
				stacks.set(slot++, whitelisted.copy());
				if (slot >= getSlots()) {
					break;
				}
			}
		}
	}

	@Override
	public int getSlots() {
		return 9;
	}

	@Override
	public boolean isItemValid(int slot, @NotNull ItemStack stack) {
		if (stack.isEmpty()) {
			return true;
		}
		for (int i = 0, slots = getSlots(); i < slots; i++) {
			if (ItemStack.isSameItemSameComponents(stack, getStackInSlot(i))) {
				//Only allow duplicates if it is the same slot as it is already stored in
				return i == slot;
			}
		}
		return true;
	}

	@Override
	public void setStackInSlot(int slot, @NotNull ItemStack stack) {
		if (isItemValid(slot, stack)) {//Ensure the stack is valid before setting it
			super.setStackInSlot(slot, stack);
		}
	}

	@Override
	public int getSlotLimit(int slot) {
		return 1;
	}

	@Override
	protected void onContentsChanged(int slot) {//TODO: Make use of the slot parameter somehow?
		if (remote) {//Skip updating the item on teh client as we already sync the data the client cares about
			return;
		}
		Set<ItemStack> targets = ItemStackLinkedSet.createTypeAndComponentsSet();
		for (int i = 0, slots = getSlots(); i < slots; ++i) {
			ItemStack stackInSlot = getStackInSlot(i);
			if (!stackInSlot.isEmpty()) {
				targets.add(stackInSlot.copyWithCount(1));
			}
		}
		invItem.update(PEDataComponentTypes.GEM_DATA, GemData.EMPTY, targets, GemData::withWhitelistSafe);
	}
}

package moze_intel.projecte.gameObjs.customRecipes;

import moze_intel.projecte.gameObjs.items.KleinStar;
import moze_intel.projecte.gameObjs.registries.PEDataComponentTypes;
import moze_intel.projecte.gameObjs.registries.PERecipeSerializers;
import net.minecraft.core.HolderLookup;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.crafting.CraftingInput;
import net.minecraft.world.item.crafting.RecipeSerializer;
import net.minecraft.world.item.crafting.ShapelessRecipe;
import org.jetbrains.annotations.NotNull;

public class RecipeShapelessKleinStar extends WrappedShapelessRecipe {

	public RecipeShapelessKleinStar(ShapelessRecipe internal) {
		super(internal);
	}

	@NotNull
	@Override
	public RecipeSerializer<?> getSerializer() {
		return PERecipeSerializers.KLEIN.get();
	}

	@NotNull
	@Override
	public ItemStack assemble(@NotNull CraftingInput inv, @NotNull HolderLookup.Provider registryAccess) {
		ItemStack result = getInternal().assemble(inv, registryAccess);
		if (result.getItem() instanceof KleinStar resultingStar) {
			long maxEmc = resultingStar.getMaximumEmc(result);
			long storedEMC = 0;
			for (ItemStack stack : inv.items()) {
				if (!stack.isEmpty() && stack.getItem() instanceof KleinStar star) {
					long inputEmc = star.getStoredEmc(stack);
					if (inputEmc >= maxEmc - storedEMC) {
						//If the emc stored in the input is more than how much we need to get to the max emc
						// just set it to the max and break out
						storedEMC = maxEmc;
						break;
					} else {
						//Otherwise we have room for the input emc, add it. We know this shouldn't overflow
						storedEMC += inputEmc;
					}
				}
			}
			result.set(PEDataComponentTypes.STORED_EMC, storedEMC);
		}
		return result;
	}
}

package moze_intel.projecte.gameObjs.customRecipes;

import net.minecraft.core.HolderLookup;
import net.minecraft.core.NonNullList;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.crafting.CraftingBookCategory;
import net.minecraft.world.item.crafting.CraftingInput;
import net.minecraft.world.item.crafting.CraftingRecipe;
import net.minecraft.world.item.crafting.Ingredient;
import net.minecraft.world.item.crafting.ShapelessRecipe;
import net.minecraft.world.level.Level;
import org.jetbrains.annotations.NotNull;

//From Mekanism's shaped recipe wrapper
public abstract class WrappedShapelessRecipe implements CraftingRecipe {

    private final ShapelessRecipe internal;

    protected WrappedShapelessRecipe(ShapelessRecipe internal) {
        this.internal = internal;
    }

    public ShapelessRecipe getInternal() {
        return internal;
    }

    @NotNull
    @Override
    public CraftingBookCategory category() {
        return internal.category();
    }

    @NotNull
    @Override
    public abstract ItemStack assemble(@NotNull CraftingInput inv, @NotNull HolderLookup.Provider registryAccess);

    @Override
    public boolean matches(@NotNull CraftingInput inv, @NotNull Level world) {
        //Note: We do not override the matches method if it matches ignoring data components,
        // to ensure that we return the proper value for if there is a match that gives a proper output
        return internal.matches(inv, world) && !assemble(inv, world.registryAccess()).isEmpty();
    }

    @Override
    public boolean canCraftInDimensions(int width, int height) {
        return internal.canCraftInDimensions(width, height);
    }

    @NotNull
    @Override
    public ItemStack getResultItem(@NotNull HolderLookup.Provider registryAccess) {
        return internal.getResultItem(registryAccess);
    }

    @NotNull
    @Override
    public NonNullList<ItemStack> getRemainingItems(@NotNull CraftingInput inv) {
        return internal.getRemainingItems(inv);
    }

    @NotNull
    @Override
    public NonNullList<Ingredient> getIngredients() {
        return internal.getIngredients();
    }

    @Override
    public boolean isSpecial() {
        return internal.isSpecial();
    }

    @NotNull
    @Override
    public String getGroup() {
        return internal.getGroup();
    }

    @NotNull
    @Override
    public ItemStack getToastSymbol() {
        return internal.getToastSymbol();
    }

    @Override
    public boolean isIncomplete() {
        return internal.isIncomplete();
    }
}

